/**
 * B09: the offline web build. The worker source is generated by tools/serviceWorkerPlugin.ts; here it runs in a vm against
 * fake caches. The headless offline reload of the real build is the `offline` e2e scenario (scripts/e2e/README.md).
 */
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import vm from 'node:vm';
import { afterAll, describe, expect, it, vi } from 'vitest';
import { canRegister, registerServiceWorker } from '../src/core/pwa';
import { pwaEnabled, precacheList, workerSource } from '../tools/serviceWorkerPlugin';

const scratch = mkdtempSync(join(tmpdir(), 'ashfall-sw-'));
afterAll(() => rmSync(scratch, { recursive: true, force: true }));

describe('which builds get a service worker', () => {
  it('the plain web build does; the artifact, Android and Linux builds do not', () => {
    expect(pwaEnabled({})).toBe(true);
    expect(pwaEnabled({ VITE_MODEL_FORMAT: 'json' })).toBe(false);
    expect(pwaEnabled({ ASHFALL_TARGET: 'android' })).toBe(false);
    expect(pwaEnabled({ ASHFALL_TARGET: 'linux' })).toBe(false);
    expect(pwaEnabled({ ASHFALL_PWA: '0' })).toBe(false);
  });

  it('the host build scripts set their target, and the artifact build sets the model format', () => {
    const root = new URL('..', import.meta.url);
    const read = (f: string) => readFileSync(new URL(f, root), 'utf8');
    expect(read('scripts/android/build.ts')).toContain("ASHFALL_TARGET: 'android'");
    expect(read('scripts/linux/build.ts')).toContain("ASHFALL_TARGET: 'linux'");
    expect(read('scripts/artifact/build.ts')).toContain("VITE_MODEL_FORMAT: 'json'");
    expect(read('vite.config.ts')).toContain('__PWA__');
    expect(read('src/main.ts')).toContain('enabled: __PWA__');
  });
});

describe('precache list', () => {
  it('holds the shell and hashed chunks, not maps or the model, audio and art folders', () => {
    const dir = join(scratch, 'dist');
    for (const d of ['assets/fonts', 'assets/audio', 'assets/enemies']) mkdirSync(join(dir, d), { recursive: true });
    for (const f of ['index.html', 'manifest.webmanifest', 'icon-192.png', 'assets/index-AbCd1234.js', 'assets/index-AbCd1234.js.map', 'assets/game-ui-Zy9x8w7v.css', 'assets/fonts/rajdhani.woff2', 'assets/audio/music.ogg', 'assets/enemies/colonist.glb', 'sw.js']) {
      writeFileSync(join(dir, f), 'x');
    }
    expect(precacheList(dir)).toEqual(['assets/fonts/rajdhani.woff2', 'assets/game-ui-Zy9x8w7v.css', 'assets/index-AbCd1234.js', 'icon-192.png', 'index.html', 'manifest.webmanifest']);
  });
});

// ---- the worker, run against fakes ----------------------------------------------------------------------------
type Listener = (event: Record<string, unknown>) => void;

function boot(files: string[], built: number, store: Map<string, Map<string, Response>>, network: (url: string) => Promise<Response>) {
  const listeners = new Map<string, Listener>();
  const cacheOf = (name: string) => {
    if (!store.has(name)) store.set(name, new Map());
    const m = store.get(name)!;
    const keyOf = (r: Request | string) => new URL(typeof r === 'string' ? r : r.url, 'https://game.test/').pathname.replace(/^\/$/, '/index.html');
    return {
      addAll: async (reqs: Request[]) => {
        for (const r of reqs) m.set(keyOf(r), await network(r.url));
      },
      put: async (r: Request, res: Response) => void m.set(keyOf(r), res),
      match: async (r: Request) => m.get(keyOf(r))?.clone(),
    };
  };
  const caches = {
    open: async (name: string) => cacheOf(name),
    keys: async () => [...store.keys()],
    delete: async (name: string) => store.delete(name),
    match: async (r: Request) => {
      for (const name of store.keys()) {
        const hit = await cacheOf(name).match(r);
        if (hit) return hit;
      }
      return undefined;
    },
  };
  const claimed = vi.fn();
  const skipped = vi.fn();
  const self = {
    location: { origin: 'https://game.test' },
    addEventListener: (type: string, fn: Listener) => listeners.set(type, fn),
    skipWaiting: async () => skipped(),
    clients: { claim: async () => claimed() },
  };
  const request = (path: string, init: { mode?: string; headers?: Record<string, string>; method?: string } = {}) => {
    const req = new Request(`https://game.test${path}`, { method: init.method ?? 'GET', ...(init.headers ? { headers: init.headers } : {}) });
    Object.defineProperty(req, 'mode', { value: init.mode ?? 'cors' });
    return req;
  };
  // Browsers resolve a relative Request against the worker's URL; Node needs a base.
  class WorkerRequest extends Request {
    constructor(input: RequestInfo | URL, init?: RequestInit) {
      super(typeof input === 'string' ? new URL(input, 'https://game.test/').href : input, init);
    }
  }
  const sandbox = { self, caches, fetch: (r: Request) => network(r.url), Request: WorkerRequest, Response, URL, Promise, console };
  vm.runInNewContext(workerSource(files, built), sandbox);
  const message = async (data: unknown) => {
    let p: Promise<unknown> = Promise.resolve();
    listeners.get('message')!({ data, waitUntil: (x: Promise<unknown>) => (p = x) });
    await p;
  };
  const run = async (type: 'install' | 'activate') => {
    let p: Promise<unknown> = Promise.resolve();
    listeners.get(type)!({ waitUntil: (x: Promise<unknown>) => (p = x) });
    await p;
  };
  const fetchEvent = async (req: Request): Promise<Response | 'passed'> => {
    let out: Promise<Response> | null = null;
    listeners.get('fetch')!({ request: req, respondWith: (p: Promise<Response>) => (out = p) });
    return out ? await out : 'passed';
  };
  return { run, fetchEvent, request, message, claimed, skipped };
}

const ok = (body: string) => new Response(body, { status: 200 });

describe('worker behaviour', () => {
  const files = ['index.html', 'assets/index-AbCd1234.js'];
  const net = (online: { value: boolean }, log: string[] = []) => async (url: string) => {
    log.push(new URL(url).pathname);
    if (!online.value) throw new TypeError('offline');
    return ok(`net:${new URL(url).pathname}`);
  };

  it('install precaches the shell and skips waiting; activate claims clients and keeps only the two newest caches', async () => {
    const store = new Map<string, Map<string, Response>>();
    for (const old of ['ashfall-0000000000001-aaaa', 'ashfall-0000000000002-bbbb', 'other-app']) store.set(old, new Map());
    const w = boot(files, 3, store, net({ value: true }));
    await w.run('install');
    expect(w.skipped).toHaveBeenCalled();
    const current = [...store.keys()].find((k) => k.startsWith('ashfall-0000000000003'))!;
    expect([...store.get(current)!.keys()].sort()).toEqual(['/assets/index-AbCd1234.js', '/index.html']);
    await w.run('activate');
    expect(w.claimed).toHaveBeenCalled();
    expect([...store.keys()].filter((k) => k.startsWith('ashfall-')).sort()).toEqual([current, 'ashfall-0000000000002-bbbb'].sort());
    expect(store.has('other-app')).toBe(true);
  });

  it('a new build has a different cache name, so an update is never answered from the old cache', () => {
    const a = workerSource(files, 100);
    const b = workerSource(['index.html', 'assets/index-NewHash1.js'], 200);
    expect(a).not.toBe(b);
    expect(/const BUILD = '(\d{13}-[0-9a-f]{10})'/.exec(a)![1]).not.toBe(/const BUILD = '(\d{13}-[0-9a-f]{10})'/.exec(b)![1]);
  });

  it('the page is fetched network-first, and served from the cache when offline', async () => {
    const store = new Map<string, Map<string, Response>>();
    const online = { value: true };
    const w = boot(files, 1, store, net(online));
    await w.run('install');
    const nav = w.request('/', { mode: 'navigate' });
    expect(await (await w.fetchEvent(nav) as Response).text()).toBe('net:/');
    online.value = false;
    expect(await (await w.fetchEvent(w.request('/', { mode: 'navigate' })) as Response).text()).toBe('net:/');
  });

  it('hashed scripts come from the cache without the network; unhashed assets are cached on first use and refreshed behind', async () => {
    const store = new Map<string, Map<string, Response>>();
    const online = { value: true };
    const log: string[] = [];
    const w = boot(files, 1, store, net(online, log));
    await w.run('install');
    log.length = 0;
    expect(await (await w.fetchEvent(w.request('/assets/index-AbCd1234.js')) as Response).text()).toBe('net:/assets/index-AbCd1234.js');
    expect(log).toEqual([]);
    // A model: first fetch goes to the network and is kept; offline it is still there.
    expect(await (await w.fetchEvent(w.request('/assets/enemies/colonist.glb')) as Response).text()).toBe('net:/assets/enemies/colonist.glb');
    online.value = false;
    expect(await (await w.fetchEvent(w.request('/assets/enemies/colonist.glb')) as Response).text()).toBe('net:/assets/enemies/colonist.glb');
  });

  it('keeps the files the page fetched before the worker was in control, so the first visit works offline', async () => {
    const store = new Map<string, Map<string, Response>>();
    const online = { value: true };
    const log: string[] = [];
    const w = boot(files, 1, store, net(online, log));
    await w.run('install');
    await w.message({
      type: 'warm',
      urls: ['https://game.test/assets/vfx/atlas.webp', 'https://game.test/sw.js', 'https://elsewhere.test/x.png', 'https://game.test/assets/index-AbCd1234.js'],
    });
    // The atlas was fetched; the worker itself, a foreign file and an already cached chunk were not.
    expect(log.filter((p) => !p.startsWith('/index') && p !== '/assets/index-AbCd1234.js')).toEqual(['/assets/vfx/atlas.webp']);
    online.value = false;
    expect(await (await w.fetchEvent(w.request('/assets/vfx/atlas.webp')) as Response).text()).toBe('net:/assets/vfx/atlas.webp');
    // Messages that are not warm-ups are ignored.
    await w.message({ type: 'other' });
    await w.message(null);
  });

  it('leaves alone what it should: other origins, non-GET and byte-range requests', async () => {
    const store = new Map<string, Map<string, Response>>();
    const w = boot(files, 1, store, net({ value: true }));
    await w.run('install');
    expect(await w.fetchEvent(w.request('/assets/audio/a.ogg', { headers: { Range: 'bytes=0-9' } }))).toBe('passed');
    expect(await w.fetchEvent(w.request('/api', { method: 'POST' }))).toBe('passed');
    const foreign = new Request('https://elsewhere.test/x.js');
    expect(await w.fetchEvent(foreign)).toBe('passed');
  });

  it('an offline request for something never cached fails instead of hanging', async () => {
    const store = new Map<string, Map<string, Response>>();
    const online = { value: true };
    const w = boot(files, 1, store, net(online));
    await w.run('install');
    online.value = false;
    const res = (await w.fetchEvent(w.request('/assets/props/never.glb'))) as Response;
    expect(res.type).toBe('error');
  });

  it('an old tab can still load its lazy chunk from the previous cache after an update', async () => {
    const store = new Map<string, Map<string, Response>>();
    store.set('ashfall-0000000000001-aaaa', new Map([['/assets/panel-OldHash1.js', ok('old chunk')]]));
    const online = { value: false };
    const w = boot(files, 2, store, net(online));
    expect(await (await w.fetchEvent(w.request('/assets/panel-OldHash1.js')) as Response).text()).toBe('old chunk');
  });
});

describe('registration', () => {
  const sw = () => {
    const listeners = new Map<string, () => void>();
    const register = vi.fn().mockResolvedValue({ scope: '/' });
    return { container: { controller: null as unknown, register, addEventListener: (t: string, fn: () => void) => listeners.set(t, fn) } as unknown as ServiceWorkerContainer, register, fire: (t: string) => listeners.get(t)?.() };
  };
  const base = (container: ServiceWorkerContainer | undefined, over: Partial<Parameters<typeof registerServiceWorker>[0]> = {}) => ({
    enabled: true,
    nav: container ? { serviceWorker: container } : {},
    loc: { protocol: 'https:', hostname: 'game.test' },
    onUpdate: vi.fn(),
    whenLoaded: (fn: () => void) => fn(),
    ...over,
  });

  it('registers ./sw.js on https and localhost, and never when disabled, unsupported or on a custom scheme', () => {
    const s = sw();
    expect(registerServiceWorker(base(s.container))).toBe(true);
    expect(s.register).toHaveBeenCalledWith('./sw.js');
    expect(canRegister(base(s.container, { loc: { protocol: 'http:', hostname: 'localhost' } }))).toBe(true);
    expect(canRegister(base(s.container, { enabled: false }))).toBe(false);
    expect(canRegister(base(undefined))).toBe(false);
    expect(canRegister(base(s.container, { loc: { protocol: 'http:', hostname: 'example.com' } }))).toBe(false);
    expect(canRegister(base(s.container, { loc: { protocol: 'app:', hostname: 'ashfall' } }))).toBe(false);
    expect(canRegister(base(s.container, { loc: { protocol: 'https:', hostname: 'appassets.androidplatform.net' }, enabled: false }))).toBe(false);
  });

  it('hands the page\'s early downloads to the active worker', async () => {
    const postMessage = vi.fn();
    const container = { controller: null, register: vi.fn().mockResolvedValue({ scope: '/' }), addEventListener: () => {}, ready: Promise.resolve({ active: { postMessage } }) } as unknown as ServiceWorkerContainer;
    registerServiceWorker(base(container, { resources: () => ['https://game.test/assets/a.webp'] }));
    await new Promise((r) => setTimeout(r, 0));
    expect(postMessage).toHaveBeenCalledWith({ type: 'warm', urls: ['https://game.test/assets/a.webp'] });
  });

  it('tells the page about an update only when an older worker was already in control', () => {
    const first = sw();
    const env1 = base(first.container);
    registerServiceWorker(env1);
    first.fire('controllerchange'); // first install claiming the page: not an update
    expect(env1.onUpdate).not.toHaveBeenCalled();
    const again = sw();
    (again.container as unknown as { controller: unknown }).controller = {};
    const env2 = base(again.container);
    registerServiceWorker(env2);
    again.fire('controllerchange');
    again.fire('controllerchange');
    expect(env2.onUpdate).toHaveBeenCalledTimes(1);
  });
});
